_ex = ['The sales map has seven steps: listing, enquiry, viewing, test drive, paperwork, payment, handover, with the seller duty named at each step.', 'The inspection finds a service record showing 78,000 km two years ago while the dash reads 62,000. The car is not listed until the history is checked.', "Listing: 'Hatchback, 2018, 62,000 km, one scratch on rear bumper (photo 14), full service history, two keys', with 24 photos.", 'Cost 7,200 plus preparation 400; five similar cars list at 8,300 to 8,900; price 8,500 leaves 900 margin.', "Enquiry reply in under 2 hours: 'Here are underbody photos and the mechanic's note. Would a video call suit you?'", 'Test drive: licence and insurance checked, route avoids busy roads, accompanied, condition recorded before and after.', 'Payment by bank transfer confirmed before keys are released; receipt and ownership transfer are given the same day.', 'A week later the buyer calls about a brake light; it is fixed free and the buyer leaves a good review.']
_extra = ['Learn the local steps to transfer ownership and register a change of keeper.', 'Keep copies of all documents for the legal period.', 'Add a short line on the warranty you offer, in plain words.', 'Check recalls and open safety notices for the model.', 'Invite the buyer to bring their own inspector if they wish.', 'Never promise features you cannot prove.', "Avoid pressure phrases such as 'only today'.", "Describe tyre tread in millimetres, not in words like 'good'.", 'Keep keys, manuals and spare wheels listed in the sale.', 'Insure test drives with a clear policy.', 'Keep a log of enquiries and outcomes.', 'Reply to complaints within two working days.', 'Offer to take back a car if a hidden major fault is found, per the law.', 'Check that your adverts do not mislead on finance costs.', 'Review monthly the cars that take longest to sell.', 'Share lessons with your trade peers.']
C['deep']['mods'] = [(m[0], _ex[i], m[2]) for i, m in enumerate(C['deep']['mods'])]
C['deep']['extra'] = [_extra[2*i:2*i+2] for i in range(8)]
_np = [['Map the full customer journey from search to handover, listing who does what at each step, and time each step so you can promise realistic delivery dates.', 'Decide which stock you will handle, such as vehicles under ten years old, and write the standards a vehicle must meet before it is listed.'], ['Verify identity details, the registration number and service history against the paperwork, and check that no money is owed on the vehicle before you list it.', 'Use a written inspection list covering tyres, brakes, lights, fluid levels and warning lights, and record the date and name of the person who completed it.'], ['Photograph every vehicle from at least 20 angles, including damage, in daylight, and write the description from the inspection list so wording matches what you can show.', 'State the mileage, previous owners and any known faults plainly, as an honest note of a small scratch builds more trust than a discovered surprise.'], ['Research at least five comparable listings, note the spread between the lowest and highest, and set your price with a stated margin above your total costs.', 'Review prices every two weeks and reduce by a planned step, such as 2 percent, for vehicles unsold after 30 days instead of guessing.'], ['Reply to every enquiry within one working hour during opening times, using a template that answers the common questions and invites a call or viewing.', 'Offer a live video walk-round for distant buyers, and keep a list of questions asked so you can improve the listing text.'], ["Confirm viewings in writing with address, time and what to bring, check the driver's licence and insurance before a test drive, and set a fixed route and time.", 'Have a second person present for each test drive, and record fuel level and mileage before and after in a short checklist.'], ['Provide a written sales contract listing the price, deposit, vehicle details, known faults and handover date, and give the buyer a copy before any payment is taken.', 'Accept payment only by traceable methods, issue a receipt, and complete a handover checklist covering keys, documents, fuel level and a final walk-round.'], ['Contact each buyer after one week and one month to ask whether anything needs attention, and keep a log of complaints with how and when each was resolved.', 'Review monthly numbers for days to sell, margin and enquiries per listing, and use them to decide which stock to buy next.']]
C['mods'] = [(m[0], m[1], list(m[2])+_np[i], m[3], m[4], m[5]) for i, m in enumerate(C['mods'])]
